package dev.riserecode;
import dev.riserecode.ui.clickgui.ClickGui;
import dev.riserecode.ui.component.*;
import dev.riserecode.map.*;
import dev.riserecode.setting.DoubleSetting;
import net.fabricmc.fabric.api.client.gametest.v1.context.ClientGameTestContext;
import net.minecraft.client.input.KeyEvent;
import java.util.*;

/** Recovery and stable identities in actual small-window client workflows. */
public final class UxRecoveryIntegrationTest {
    private static int checks;
    private static void check(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
    private static void key(ClientGameTestContext c,int code){c.getInput().pressKey(code);c.waitTicks(2);}
    private static String label(net.minecraft.client.Minecraft mc){return mc.gui.screen() instanceof WaypointScreen w?w.focusedControlLabel():Client.INSTANCE.getClickGui().focusedControlLabel();}
    private static void focus(ClientGameTestContext c,String prefix){for(int i=0;i<230;i++){key(c,258);if(c.computeOnClient(mc->label(mc).startsWith(prefix)))return;}throw new AssertionError("Cannot reach "+prefix);}
    public static void run(ClientGameTestContext c){
        c.waitFor(mc->Client.INSTANCE.isInitialized()&&Client.INSTANCE.resourcesReady()&&mc.gui.overlay()==null,1200);
        var maps=Client.INSTANCE.getMaps();var snapshot=c.computeOnClient(mc->maps.waypoints().snapshot());var friends=c.computeOnClient(mc->Client.INSTANCE.getFriendManager().getFriends());
        int[] original=c.computeOnClient(mc->new int[]{mc.getWindow().getScreenWidth(),mc.getWindow().getScreenHeight(),mc.options.guiScale().get()});
        c.getInput().resizeWindow(960,720);
        c.runOnClient(mc->{mc.options.guiScale().set(3);Client.INSTANCE.getThemeManager().reset();for(var pair:Map.of("Font Scale",2.0,"Window Width",360.0,"Window Height",240.0,"Content Padding",20.0).entrySet()){((DoubleSetting)Client.INSTANCE.getThemeManager().getSetting(pair.getKey())).setValue(pair.getValue());}var gui=Client.INSTANCE.getClickGui();gui.open(null);gui.selectPage(ClickGui.Page.COSMETICS);var e=gui.getCosmeticsEditor();var def=Client.INSTANCE.getCosmetics().library().definitions().stream().filter(d->Client.INSTANCE.getCosmetics().library().available(d)).findFirst().orElseThrow();e.select(def.id());e.buttons().stream().filter(b->b.label().equals("Edit")).findFirst().orElseThrow().activate();});c.waitTicks(20);
        var draft=c.computeOnClient(mc->Client.INSTANCE.getClickGui().getCosmeticsEditor().draft());
        c.runOnClient(mc->mc.gui.screen().keyPressed(new KeyEvent(70,0,2)));c.waitTicks(4);c.getInput().typeChars("Bee");c.waitTicks(3);
        c.runOnClient(mc->{var e=Client.INSTANCE.getClickGui().getCosmeticsEditor();check(e.search().isFocused()&&e.search().getValue().equals("Bee"),"Ctrl F exposes visible cosmetic search");check(!e.isEditing()&&e.search().getBounds().width()>0,"Search returns to visible browse chrome");check(e.draft().equals(draft),"Search preserves outfit draft");});c.takeScreenshot("ux6-cosmetic-visible-search-font2");
        c.runOnClient(mc->{var e=Client.INSTANCE.getClickGui().getCosmeticsEditor();e.buttons().stream().filter(b->b.label().equals("Edit")).findFirst().orElseThrow().activate();});c.waitTicks(3);
        c.runOnClient(mc->{check(!Client.INSTANCE.getClickGui().getCosmeticsEditor().search().isFocused()&&!FocusedInput.active(),"Hidden compact search releases keyboard ownership");Client.INSTANCE.getClickGui().getCosmeticsEditor().discard();var store=maps.waypoints();for(int i=0;i<24;i++)store.put(new WaypointStore.Waypoint(new UUID(6,i),String.format("Journey%02d",i),i,64,i,"minecraft:overworld","",0xFF64D8C4,true,false,false));mc.gui.setScreen(new WaypointScreen(Client.INSTANCE.getClickGui(),maps));});c.waitTicks(5);
        focus(c,"Journey23, visibility");key(c,257);c.runOnClient(mc->check(label(mc).startsWith("Journey23, visibility, hidden"),"Waypoint visibility mutation retains named action focus"));key(c,258);c.runOnClient(mc->check(label(mc).startsWith("Journey23, tracking"),"Forward traversal continues within same waypoint"));key(c,257);c.runOnClient(mc->check(label(mc).contains("tracking, true"),"Tracking mutation retains action identity"));c.takeScreenshot("ux6-waypoint-last-mutation-font2");
        c.runOnClient(mc->mc.gui.screen().keyPressed(new KeyEvent(258,0,1)));c.waitTicks(2);c.runOnClient(mc->mc.gui.screen().keyPressed(new KeyEvent(258,0,1)));c.waitTicks(2);key(c,257);c.runOnClient(mc->check(mc.gui.screen() instanceof WaypointEditScreen,"Keyboard opens same waypoint editor"));c.runOnClient(mc->mc.gui.screen().onClose());c.waitTicks(4);c.runOnClient(mc->check(label(mc).startsWith("Journey23, edit waypoint"),"Editor return restores exact waypoint action"));
        focus(c,"Journey23, delete waypoint");key(c,257);key(c,256);c.waitTicks(4);c.runOnClient(mc->check(maps.waypoints().all().stream().anyMatch(p->p.name().equals("Journey23")),"Cancel deletion retains waypoint"));
        focus(c,"Journey23, delete waypoint");key(c,257);c.runOnClient(mc->{var screen=mc.gui.screen();var yes=screen.children().stream().filter(v->v instanceof net.minecraft.client.gui.components.Button b&&b.getMessage().getString().equals("Yes")).map(net.minecraft.client.gui.components.Button.class::cast).findFirst().orElseThrow();yes.onPress(new KeyEvent(257,0,0));});c.waitTicks(4);c.runOnClient(mc->{check(maps.waypoints().all().stream().noneMatch(p->p.name().equals("Journey23")),"Confirmed removal deletes intended UUID");check(!label(mc).isEmpty(),"Waypoint removal focuses predictable neighbor");mc.gui.screen().onClose();var fm=Client.INSTANCE.getFriendManager();fm.add("JourneyFriendA",new UUID(6,100));fm.add("JourneyFriendB",new UUID(6,101));Client.INSTANCE.getClickGui().selectPage(ClickGui.Page.FRIENDS);});c.waitTicks(5);
        focus(c,"JourneyFriendA, button");key(c,257);c.runOnClient(mc->check(Client.INSTANCE.getFriendManager().isFriend("JourneyFriendA"),"Friend name inspection cannot remove identity"));focus(c,"Remove JourneyFriendA, button");key(c,257);key(c,256);c.waitTicks(4);c.runOnClient(mc->check(Client.INSTANCE.getFriendManager().isFriend(new UUID(6,100),"JourneyFriendA"),"Cancel removal preserves original friend UUID"));key(c,257);c.runOnClient(mc->{var yes=mc.gui.screen().children().stream().filter(v->v instanceof net.minecraft.client.gui.components.Button b&&b.getMessage().getString().equals("Yes")).map(net.minecraft.client.gui.components.Button.class::cast).findFirst().orElseThrow();yes.onPress(new KeyEvent(257,0,0));});c.waitTicks(4);c.runOnClient(mc->{check(!Client.INSTANCE.getFriendManager().isFriend("JourneyFriendA"),"Explicit confirmed friend removal succeeds");check(Client.INSTANCE.getClickGui().focusedControlLabel().startsWith("JourneyFriendB"),"Removal focuses neighboring friend");Client.INSTANCE.getClickGui().selectPage(ClickGui.Page.RESOURCES);var e=Client.INSTANCE.getClickGui().getResourcesEditor();e.toggle(Client.INSTANCE.getResourcesManager().library().catalog().entries().getFirst());});c.waitTicks(6);
        c.waitFor(mc->!Client.INSTANCE.getResourcesManager().library().progress().running(),1200);c.runOnClient(mc->Client.INSTANCE.getResourcesManager().library().start(true));c.waitFor(mc->!Client.INSTANCE.getResourcesManager().library().progress().running(),600);c.waitTicks(4);
        c.runOnClient(mc->Client.INSTANCE.getClickGui().getKeyboardNavigation().pointerUsed());for(int i=0;i<12;i++){c.runOnClient(mc->mc.gui.screen().keyPressed(new KeyEvent(258,0,1)));c.waitTicks(2);if(c.computeOnClient(mc->label(mc).startsWith("Cache incomplete"))){break;}}c.runOnClient(mc->{String name=label(mc);check(name.contains("Cache resources in Tools before Apply")&&name.contains("retry"),"Failure help exposes Apply reason and recovery to keyboard");});key(c,257);c.waitTicks(20);c.runOnClient(mc->check(label(mc).startsWith("Cache all, button"),"Activating status reveals and focuses cache recovery"));c.takeScreenshot("ux6-resources-keyboard-retry-font2");
        c.runOnClient(mc->{Client.INSTANCE.getClickGui().getResourcesEditor().discard();Client.INSTANCE.getFriendManager().replace(friends);maps.waypoints().load(snapshot);Client.INSTANCE.getThemeManager().reset();mc.gui.setScreen(null);});c.getInput().resizeWindow(original[0],original[1]);c.runOnClient(mc->mc.options.guiScale().set(original[2]));
        Client.INSTANCE.getLogger().info("UX recovery workflow checks passed: {}",checks);
    }
}
